using UnityEngine;using UnityEngine.InputSystem;using AstroGateway.NativeSlice;
namespace AstroGateway.CinematicHUD {
[DefaultExecutionOrder(-200)]public class HUDInputRouter:MonoBehaviour {
 public AstroGatewayHUDController hud;
 void Update(){var g=hud.game;if(!g||!g.initialized||g.testing)return;if(Keyboard.current?.escapeKey.wasPressedThisFrame==true)hud.TogglePause();if(Keyboard.current?.f1Key.wasPressedThisFrame==true)hud.CycleVisibility();if(!hud.InputAllowed){g.modes.Submit(default);g.prototype.testMove=Vector2.zero;g.prototype.testLook=Vector2.zero;hud.lookDelta=Vector2.zero;return;}NativeInput i=new NativeInput{movement=hud.movement,look=hud.lookDelta,run=hud.runHeld,accelerate=g.prototype.driving&&hud.runHeld,brake=hud.brakeHeld};hud.lookDelta=Vector2.zero;var k=Keyboard.current;var m=Mouse.current;if(k!=null&&!k.leftMetaKey.isPressed&&!k.leftCtrlKey.isPressed){i.movement+=new Vector2((k.dKey.isPressed?1:0)-(k.aKey.isPressed?1:0),(k.wKey.isPressed?1:0)-(k.sKey.isPressed?1:0));i.run|=k.leftShiftKey.isPressed;i.brake|=k.spaceKey.isPressed;if(k.eKey.wasPressedThisFrame&&Vector3.Distance(g.prototype.ActivePosition(),g.prototype.rover.transform.position)<=5)hud.Interact();if(k.kKey.wasPressedThisFrame)hud.BeginScan();if(k.digit1Key.wasPressedThisFrame)g.prototype.SetWeather(0);if(k.digit2Key.wasPressedThisFrame)g.prototype.SetWeather(1);if(k.digit3Key.wasPressedThisFrame)g.prototype.SetWeather(2);}if(m!=null&&m.rightButton.isPressed)i.look+=m.delta.ReadValue();g.modes.Submit(hud.InputAllowed?i:default);}
}}
